; The Rust hooks' NASM entries (generated by hooks_026g.py from the patches' <patch>.toml: do not edit).
; Each entry (RUST_CALL, rust_hook_026g.inc) presents a site's arguments to
; its shim and cleans up as the game's function did. The arena's block
; patches.code (with the crate); link_026g.py installs each site.
bits 32
section .text
%include "rust_hook_026g.inc"

; 0x27b92d process_static_match_info after its match_options::deserialize (0x27B928): esi the options, the reader at [ebp-2Ch]: lohook -> blackout_on_static_info
global blackout_on_static_info
extern hook_blackout_on_static_info
blackout_on_static_info:
    lea esp, [esp - 4]
    pushfd
    pushad
    cld
    mov ebp, esp
    sub esp, 512
    and esp, -16
    fxsave [esp]
    mov edi, esp
    sub esp, 8
    and esp, -16
    mov [esp], ebp
    mov [esp+4], edi
    mov eax, esp
    sub esp, 12
    push eax
    call hook_blackout_on_static_info
    mov edx, blackout_on_static_info_replay
    cmp eax, 0
    je blackout_on_static_info_go
    mov edx, 0x27b932
    cmp eax, 1
    je blackout_on_static_info_go
    ud2
blackout_on_static_info_go:
    mov [ebp + 36], edx
    fxrstor [edi]
    mov esp, ebp
    popad
    popfd
    ret
blackout_on_static_info_replay:
    db 0x8b, 0x17, 0x8b, 0x42, 0x40
    jmp 0x27b932

